<?php elseif(in_array($type,['gallery','image'],true)): ?><section class="<?= e($class) ?>"><div class="pb-inner"><?php if($title): ?><h2><?= e($title) ?></h2><?php endif; ?><?php if($type==='image'&&$image): ?><img src="<?= e($image) ?>" alt="<?= e($title) ?>" style="display:block;width:100%;max-height:520px;object-fit:cover;border-radius:14px"><?php else: ?><div class="pb-gallery pb-layout-<?= e($pbSlug($style)) ?>"><?php foreach(($stylePhotos??[]) as $i=>$src): ?><img src="<?= e($image?:$src) ?>" alt="<?= e($title?:'Tatil galerisi') ?>" loading="lazy"><?php endforeach; ?></div><?php endif; ?></div></section>
<?php elseif(in_array($type,['image_text','text','quote','features','services','faq','testimonials','stats','newsletter','contact','map','video','blog','logos','team','awards','pricing','social','countdown','trust','steps','timeline','icon_list','nearby','amenities','seasonal','promo','banner','cta','hosts','review_summary','html'],true)): ?><section class="<?= e($class) ?>"><div class="pb-inner"><?php if($type==='image_text'): ?><div class="pb-image-text"><div><?php if($eyebrow): ?><span class="pb-eyebrow"><?= e($eyebrow) ?></span><?php endif; ?><h2><?= e($title) ?></h2><p class="pb-lead"><?= e($subtitle?:$description) ?></p><?php if($buttonText&&$buttonUrl): ?><a class="pb-button" href="<?= e($buttonUrl) ?>"><?= e($buttonText) ?></a><?php endif; ?></div><?php if($image): ?><img src="<?= e($image) ?>" alt="<?= e($title) ?>"><?php endif; ?></div><?php elseif(in_array($type,['cta','banner','hosts','promo','booking_cta'],true)): ?><div class="pb-banner"><?php if($image): ?><img src="<?= e($image) ?>" alt="" style="width:150px;max-height:120px;object-fit:cover;border-radius:10px"><?php endif; ?><div><h2><?= e($title) ?></h2><p class="pb-lead"><?= e($subtitle?:$description) ?></p></div><?php if($buttonText&&$buttonUrl): ?><a class="pb-button" href="<?= e($buttonUrl) ?>"><?= e($buttonText) ?></a><?php endif; ?></div><?php else: ?><div class="<?= $align==='center'?'pb-text-center':'' ?>"><?php if($eyebrow): ?><span class="pb-eyebrow"><?= e($eyebrow) ?></span><?php endif; ?><h2><?= e($title) ?></h2><?php if($subtitle): ?><p class="pb-lead"><?= e($subtitle) ?></p><?php endif; ?><?php if($description): ?><p class="pb-lead"><?= e($description) ?></p><?php endif; ?><?php if($buttonText&&$buttonUrl): ?><a class="pb-button" href="<?= e($buttonUrl) ?>"><?= e($buttonText) ?></a><?php endif; ?></div><?php endif; ?></div></section>
